-- VerifAI AI Lab — capstone papers. Each is split into sections (Section A/B,
-- and C for case-study papers). Settings applied per product decision:
-- 75 marks, 90 minutes, 60% pass, 3 attempts, 70 XP + 15 tokens + badge.
-- The case-study scenario is shown with each question on the paper (not on the
-- instructions screen). Idempotent: assessments upsert by code; questions are
-- replaced. Question marks must sum to total_marks, and rubric criteria must sum
-- to the question's marks.

INSERT INTO achievements (code, name, description) VALUES ('capstone-finance', 'Finance Capstone', 'Passed the Finance module capstone assessment.')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

INSERT INTO lab_capstone_assessments
  (code, track_id, title, summary, scenario, instructions, total_marks, grade_bands,
   time_limit_seconds, pass_score, max_attempts, xp_reward, token_reward, achievement_code, sort_order)
VALUES ('cap-fin', (SELECT id FROM industry_tracks WHERE name = 'Finance'),
  'Finance Capstone: Mokoena Print Studio', 'Thabo Mokoena owns a small print shop in Gauteng. He is considering buying a digital press and has asked you, as his finance adviser, for a recommendation.', '{"title":"Mokoena Print Studio (Pty) Ltd","background":"Thabo Mokoena owns a small print shop in Gauteng. He is considering buying a digital press and has asked you, as his finance adviser, for a recommendation.","facts":["The press costs R480,000 today and has no resale value after 4 years.","It is expected to bring in net cash inflows of R160,000 at the end of each of the next 4 years.","Thabo''s required return is 10% per year.","Current working capital: inventory is held for 45 days, customers pay after 60 days, and suppliers are paid after 30 days.","Last year the studio reported a net profit of R120,000, yet its bank balance fell by R90,000.","Current assets are R350,000 and current liabilities are R280,000."]}'::jsonb, '["Answer ALL questions. The paper is worth 75 marks and must be completed in 90 minutes.","Section A (Application, 30 marks): work the numbers. You may use a calculator; round money to the nearest rand unless told otherwise.","Section B (Scenario, 45 marks): apply your results to the scenario and recommend a course of action.","The case-study scenario is shown at the top of every question for reference; scroll down to the question.","Question 6 is marked against a rubric. Write in full sentences for a non-specialist reader."]'::jsonb,
  75, '[{"label":"Distinction","min_percent":75},{"label":"Merit","min_percent":60},{"label":"Competent","min_percent":50},{"label":"Not yet competent","min_percent":0}]'::jsonb, 5400, 60, 3, 70, 15, 'capstone-finance', 10)
ON CONFLICT (code) DO UPDATE SET
  track_id = EXCLUDED.track_id, title = EXCLUDED.title, summary = EXCLUDED.summary,
  scenario = EXCLUDED.scenario, instructions = EXCLUDED.instructions, total_marks = EXCLUDED.total_marks,
  grade_bands = EXCLUDED.grade_bands, time_limit_seconds = EXCLUDED.time_limit_seconds,
  pass_score = EXCLUDED.pass_score, max_attempts = EXCLUDED.max_attempts,
  xp_reward = EXCLUDED.xp_reward, token_reward = EXCLUDED.token_reward,
  achievement_code = EXCLUDED.achievement_code, sort_order = EXCLUDED.sort_order;

DELETE FROM lab_capstone_questions WHERE assessment_id = (SELECT id FROM lab_capstone_assessments WHERE code = 'cap-fin');
INSERT INTO lab_capstone_questions
  (assessment_id, type, section, competency, cognitive_level, source_refs, prompt, payload, correct,
   explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
SELECT c.id, v.type, v.section, v.competency, v.cognitive_level, v.source_refs::jsonb, v.prompt,
       v.payload::jsonb, v.correct::jsonb, v.explanation, v.rubric::jsonb, v.model_answer,
       v.code_lines::jsonb, v.word_limit::jsonb, v.marks, v.marking, v.sort_order
FROM lab_capstone_assessments c, (VALUES
  ('numeric', 'Section A · Application', 'Capital budgeting', 'apply', '["FIN-01","FIN-03"]'::jsonb, 'Evaluate the digital press as an investment.', '{"parts":[{"label":"(a)","prompt":"Calculate the present value of the four cash inflows at 10% (nearest rand).","marks":6,"unit":null},{"label":"(b)","prompt":"Calculate the net present value (NPV) of the press (nearest rand).","marks":9,"unit":null}]}'::jsonb, '{"parts":[{"answer":507178,"tolerance":100,"marks":6},{"answer":27178,"tolerance":100,"marks":9}]}'::jsonb, 'Annuity factor at 10% for 4 years = (1 - 1.1^-4) / 0.1 = 3.1699. PV = 160,000 x 3.1699 = R507,178. NPV = 507,178 - 480,000 = R27,178.', NULL, NULL, NULL, NULL, 15, 'auto', 1),
  ('numeric', 'Section A · Application', 'Working capital', 'apply', '["FIN-04"]'::jsonb, 'Calculate the studio''s cash conversion cycle in days.', '{"unit":"days"}'::jsonb, '{"answer":75,"tolerance":0}'::jsonb, 'CCC = 45 + 60 - 30 = 75 days.', NULL, NULL, NULL, NULL, 10, 'auto', 2),
  ('multiple_choice', 'Section A · Application', 'Working capital', 'apply', '["FIN-04"]'::jsonb, 'Which ONE action would shorten Thabo''s cash conversion cycle?', '{"options":["Pay suppliers after 15 days instead of 30","Negotiate supplier terms of 45 days instead of 30","Hold more paper and ink in stock","Give customers 75 days to pay instead of 60"]}'::jsonb, '{"answer_index":1}'::jsonb, 'Longer supplier terms raise days payables, which is subtracted in the CCC. The other options lengthen the cycle.', NULL, NULL, NULL, NULL, 5, 'auto', 3),
  ('multiple_choice', 'Section B · Scenario', 'Profit vs cash', 'analyse', '["FIN-05"]'::jsonb, 'The studio made a profit of R120,000 but its bank balance fell by R90,000. Which is the MOST plausible explanation?', '{"options":["A large increase in money owed by customers and in stock on the shelves","A higher depreciation charge during the year","Paying suppliers later than in the previous year","Customers paying faster than in the previous year"]}'::jsonb, '{"answer_index":0}'::jsonb, 'Sales booked but not yet collected, and cash tied up in stock, reduce cash without reducing profit. Depreciation is non-cash, and slower payments to suppliers or faster collections would raise cash.', NULL, NULL, NULL, NULL, 6, 'auto', 4),
  ('multi_select', 'Section B · Scenario', 'Verifying AI output', 'evaluate', '["FIN-01","FIN-03","FIN-04","FIN-05"]'::jsonb, 'An AI assistant drafted this advice for Thabo. Select ALL statements that are INCORRECT.', '{"options":["A positive NPV means the project is expected to earn less than the required return, so it should be rejected.","The cash conversion cycle equals days inventory outstanding plus days sales outstanding minus days payables outstanding.","Because the studio is profitable, Thabo does not need to monitor cash flow separately.","Future value under compound interest is the present value multiplied by (1 + r) raised to the number of periods."]}'::jsonb, '{"indices":[0,2]}'::jsonb, 'Statement 1 is wrong: positive NPV means the project beats the required return. Statement 3 is wrong: profit does not guarantee cash. Statements 2 and 4 are correct.', NULL, NULL, NULL, NULL, 4, 'auto', 5),
  ('extended_response', 'Section B · Scenario', 'Recommendation', 'create', '["FIN-03","FIN-04","FIN-05"]'::jsonb, 'Write a recommendation (250 to 400 words) to Thabo on whether to buy the press. Use your NPV result, explain the cash conversion cycle and the profit-versus-cash situation, name one risk to his cash position, and give one action he can take to manage it.', '{"word_limit":{"min":250,"max":400}}'::jsonb, NULL, NULL, '[{"criterion":"Clear recommendation consistent with the NPV result (accept the press)","marks":6},{"criterion":"Cites the NPV figures (about R507,178 present value against the R480,000 cost) and explains what a positive NPV of about R27,178 means","marks":8},{"criterion":"Explains the 75-day cash conversion cycle and its components (inventory 45 + debtors 60 - creditors 30)","marks":6},{"criterion":"Identifies a cash risk, such as profit not equalling cash or paying upfront while customers take 60 days to pay","marks":6},{"criterion":"Proposes a relevant action to manage cash (collect from customers sooner, extend supplier terms, arrange financing)","marks":6},{"criterion":"Clear, professional wording a non-specialist can follow","marks":3}]'::jsonb, 'I recommend that you buy the digital press. At your required return of 10%, the four yearly inflows of R160,000 are worth about R507,178 today, against a cost of R480,000, so the net present value is about R27,178. Because that is positive, the press is expected to earn more than your required return, so it creates value for the business. However, your cash position needs care. Your cash conversion cycle is 75 days: you hold inventory for 45 days, customers take 60 days to pay, and you pay suppliers after only 30 days. Last year you made a profit of R120,000, yet your bank balance fell by R90,000, which shows that profit and cash are different things. The main risk is that if you pay R480,000 upfront while customers still take 60 days to pay, you could run short of cash even though the investment is worthwhile. To manage this, I suggest three steps: negotiate longer payment terms with your suppliers, ask customers to pay sooner (perhaps with a small discount for early payment), and arrange finance for part of the cost so you keep enough cash to run the business while the press earns its returns. I also recommend monitoring the cash conversion cycle each month and setting a target to bring it below 60 days.', NULL, '{"min":250,"max":400}'::jsonb, 35, 'rubric', 6)
) AS v(type, section, competency, cognitive_level, source_refs, prompt, payload, correct, explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
WHERE c.code = 'cap-fin';

INSERT INTO achievements (code, name, description) VALUES ('capstone-legal', 'Legal Capstone', 'Passed the Legal module capstone assessment.')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

INSERT INTO lab_capstone_assessments
  (code, track_id, title, summary, scenario, instructions, total_marks, grade_bands,
   time_limit_seconds, pass_score, max_attempts, xp_reward, token_reward, achievement_code, sort_order)
VALUES ('cap-leg', (SELECT id FROM industry_tracks WHERE name = 'Legal'),
  'Legal Capstone: TutorLink', 'Nomsa Dube founded TutorLink (Pty) Ltd, an app that connects university students with tutors. You are the company''s compliance adviser.', '{"title":"TutorLink (Pty) Ltd","background":"Nomsa Dube founded TutorLink (Pty) Ltd, an app that connects university students with tutors. You are the company''s compliance adviser.","facts":["TutorLink decides which personal information to collect from students (names, contact details, payment details) and why.","It stores this data with a cloud provider, CloudStore, which handles it only on TutorLink''s instructions.","On Monday, TutorLink discovered that an unauthorised person had accessed about 2,000 student records the previous Friday.","On Tuesday, a TutorLink sales agent phoned a student, Sipho, without being asked to. Sipho agreed to buy a premium plan. On Thursday he wants to cancel.","A tutor is suing TutorLink for R200,000 for breach of contract and has threatened to go after Nomsa personally.","TutorLink''s product team wants to quote parts of South African statutes in its AI Lab lessons."]}'::jsonb, '["Answer ALL questions. The paper is worth 75 marks and must be completed in 90 minutes.","Section A (Short answers, 15 marks): apply the law to each point briefly.","Section B (Long answers, 20 marks): explain the parties'' roles and the company-law position.","Section C (Case study, 40 marks): write a full advisory note for the scenario.","The case-study scenario is shown at the top of every question for reference.","Base your answers on South African law covered in the content (POPIA, the Consumer Protection Act, the Companies Act and the Copyright Act)."]'::jsonb,
  75, '[{"label":"Distinction","min_percent":75},{"label":"Merit","min_percent":60},{"label":"Competent","min_percent":50},{"label":"Not yet competent","min_percent":0}]'::jsonb, 5400, 60, 3, 70, 15, 'capstone-legal', 20)
ON CONFLICT (code) DO UPDATE SET
  track_id = EXCLUDED.track_id, title = EXCLUDED.title, summary = EXCLUDED.summary,
  scenario = EXCLUDED.scenario, instructions = EXCLUDED.instructions, total_marks = EXCLUDED.total_marks,
  grade_bands = EXCLUDED.grade_bands, time_limit_seconds = EXCLUDED.time_limit_seconds,
  pass_score = EXCLUDED.pass_score, max_attempts = EXCLUDED.max_attempts,
  xp_reward = EXCLUDED.xp_reward, token_reward = EXCLUDED.token_reward,
  achievement_code = EXCLUDED.achievement_code, sort_order = EXCLUDED.sort_order;

DELETE FROM lab_capstone_questions WHERE assessment_id = (SELECT id FROM lab_capstone_assessments WHERE code = 'cap-leg');
INSERT INTO lab_capstone_questions
  (assessment_id, type, section, competency, cognitive_level, source_refs, prompt, payload, correct,
   explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
SELECT c.id, v.type, v.section, v.competency, v.cognitive_level, v.source_refs::jsonb, v.prompt,
       v.payload::jsonb, v.correct::jsonb, v.explanation, v.rubric::jsonb, v.model_answer,
       v.code_lines::jsonb, v.word_limit::jsonb, v.marks, v.marking, v.sort_order
FROM lab_capstone_assessments c, (VALUES
  ('multiple_choice', 'Section A · Short answers', 'Breach notification', 'apply', '["LEG-03"]'::jsonb, 'TutorLink has reasonable grounds to believe the student records were accessed by an unauthorised person. What must it do?', '{"options":["Notify the Information Regulator and the affected students as soon as reasonably possible","Wait for the Information Regulator to discover the breach","Notify only the Information Regulator and never the students","Notify anyone only if the media reports the breach"]}'::jsonb, '{"answer_index":0}'::jsonb, 'Section 22 of POPIA requires notification of the Regulator and the affected data subjects as soon as reasonably possible.', NULL, NULL, NULL, NULL, 8, 'auto', 1),
  ('multiple_choice', 'Section A · Short answers', 'Consumer rights', 'apply', '["LEG-04"]'::jsonb, 'Can Sipho cancel the premium plan he agreed to on Tuesday?', '{"options":["No, he is bound for the full plan period once he agrees","Yes, a transaction resulting from direct marketing can be rescinded without reason or penalty within five business days","Yes, but only if he can prove the plan is defective","No, unless TutorLink agrees to cancel"]}'::jsonb, '{"answer_index":1}'::jsonb, 'Section 16 of the Consumer Protection Act gives a five-business-day cooling-off right for direct marketing. The six-month right in section 56 is about goods that fail the implied warranty of quality.', NULL, NULL, NULL, NULL, 7, 'auto', 2),
  ('matching', 'Section B · Long answers', 'POPIA roles', 'apply', '["LEG-01"]'::jsonb, 'Match each party in the scenario to its role under POPIA.', '{"left":["TutorLink","CloudStore","The university students","The body TutorLink must notify about the breach"],"right":["Information Regulator","Data subjects","Operator","Responsible party"]}'::jsonb, '{"mapping":{"TutorLink":"Responsible party","CloudStore":"Operator","The university students":"Data subjects","The body TutorLink must notify about the breach":"Information Regulator"}}'::jsonb, 'The responsible party decides why and how to process personal information and remains accountable; an operator processes it on the responsible party''s instructions.', NULL, NULL, NULL, NULL, 10, 'auto', 3),
  ('multiple_choice', 'Section B · Long answers', 'Company law', 'analyse', '["LEG-05"]'::jsonb, 'Can the tutor claim the R200,000 from Nomsa''s personal assets?', '{"options":["Yes, a director is automatically liable for the company''s debts","Generally no, because the company is a juristic person with its own legal existence; only in exceptional cases of unconscionable abuse can a court disregard this","Yes, if Nomsa is the company''s only shareholder","Only if the company''s assets are worth less than R1 million"]}'::jsonb, '{"answer_index":1}'::jsonb, 'Under the Companies Act, a company is a juristic person separate from its shareholders and directors. A court may only look past this in exceptional cases of unconscionable abuse (section 20(9)).', NULL, NULL, NULL, NULL, 10, 'auto', 4),
  ('multi_select', 'Section C · Case study', 'Verifying AI output', 'evaluate', '["LEG-02","LEG-04"]'::jsonb, 'TutorLink''s AI assistant produced this legal summary. Select ALL statements that are INCORRECT.', '{"options":["The eight conditions for lawful processing include accountability and security safeguards.","TutorLink may keep student personal information indefinitely, as long as it might be useful someday.","Under the Consumer Protection Act, a consumer can return goods that fail the implied warranty of quality within six months of delivery.","TutorLink cannot quote South African statutes in its lessons because legislation is protected by copyright."]}'::jsonb, '{"indices":[1,3]}'::jsonb, 'Statement 2 is wrong: records should not be kept longer than needed for their purpose. Statement 4 is wrong: section 12(8)(a) of the Copyright Act excludes official legislative and legal texts from copyright. Statements 1 and 3 are correct.', NULL, NULL, NULL, NULL, 4, 'auto', 5),
  ('extended_response', 'Section C · Case study', 'Advisory note', 'create', '["LEG-01","LEG-02","LEG-03"]'::jsonb, 'Write a short advisory note (250 to 400 words) to Nomsa that explains TutorLink''s immediate POPIA duties after the breach, identifies who is responsible for the data, and gives TWO steps to reduce the risk of future breaches.', '{"word_limit":{"min":250,"max":400}}'::jsonb, NULL, NULL, '[{"criterion":"Identifies TutorLink as the responsible party that remains accountable even though CloudStore holds the data, and CloudStore as the operator","marks":6},{"criterion":"States the breach duties: notify the Information Regulator AND the affected students as soon as reasonably possible","marks":8},{"criterion":"Links the breach to the security safeguards condition of POPIA","marks":5},{"criterion":"Gives at least two sensible preventive steps (e.g. stronger access controls or encryption, a written operator agreement with CloudStore, staff training, a breach response plan, collecting less data)","marks":9},{"criterion":"Applies South African law correctly (POPIA and the Consumer Protection Act) rather than generic advice","marks":5},{"criterion":"Clear structure and professional wording for a non-lawyer","marks":3}]'::jsonb, 'Nomsa, TutorLink is the responsible party under POPIA, so we remain accountable for the students'' information even though CloudStore stores it for us. CloudStore is our operator and may only process the data on our instructions. Because we have reasonable grounds to believe an unauthorised person accessed about 2,000 records, we must notify the Information Regulator and the affected students as soon as reasonably possible, and we should record what happened. The breach also suggests we did not meet the security safeguards condition, so we must investigate how it happened and why our controls failed. To reduce the risk of this happening again, I recommend at least two steps. First, tighten access controls and encrypt stored student data, so that even if access is gained the information cannot be read. Second, put in place a written agreement with CloudStore that requires it to protect the data and to report any compromise to us immediately, and train our staff on handling personal information. I also suggest collecting only the data we genuinely need and preparing a breach response plan so we can act quickly next time. On the separate matter of quoting statutes in our lessons, we may do so: section 12(8)(a) of the Copyright Act excludes official legal texts from copyright.', NULL, '{"min":250,"max":400}'::jsonb, 36, 'rubric', 6)
) AS v(type, section, competency, cognitive_level, source_refs, prompt, payload, correct, explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
WHERE c.code = 'cap-leg';

INSERT INTO achievements (code, name, description) VALUES ('capstone-it', 'IT / Software Capstone', 'Passed the IT / Software module capstone assessment.')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

INSERT INTO lab_capstone_assessments
  (code, track_id, title, summary, scenario, instructions, total_marks, grade_bands,
   time_limit_seconds, pass_score, max_attempts, xp_reward, token_reward, achievement_code, sort_order)
VALUES ('cap-it', (SELECT id FROM industry_tracks WHERE name = 'IT / Software'),
  'IT / Software Capstone: CampusConnect', 'CampusConnect is a student marketplace with a Flutter mobile app, a Node/Express API and a PostgreSQL database. The team uses an AI assistant to generate code and wants to add a model that flags fake listings. You are the reviewing engineer.', '{"title":"CampusConnect","background":"CampusConnect is a student marketplace with a Flutter mobile app, a Node/Express API and a PostgreSQL database. The team uses an AI assistant to generate code and wants to add a model that flags fake listings. You are the reviewing engineer.","facts":["The search endpoint builds its SQL by joining strings together (see Question 1).","The sign-up endpoint stores passwords using MD5 with no salt.","The maximum listing price is checked only inside the Flutter form.","The fake-listing model scores 99% accuracy on training data and 71% on validation data."]}'::jsonb, '["Answer ALL questions. The paper is worth 75 marks and must be completed in 90 minutes.","Section A (Application, 30 marks): identify the BEST fix or control for each weakness.","Section B (Scenario, 45 marks): review the code and the model and write a short pre-release report.","The case-study scenario and the code sample are shown with each question for reference.","You are reviewing code and a model that were partly produced by an AI assistant. Do not assume AI output is correct."]'::jsonb,
  75, '[{"label":"Distinction","min_percent":75},{"label":"Merit","min_percent":60},{"label":"Competent","min_percent":50},{"label":"Not yet competent","min_percent":0}]'::jsonb, 5400, 60, 3, 70, 15, 'capstone-it', 30)
ON CONFLICT (code) DO UPDATE SET
  track_id = EXCLUDED.track_id, title = EXCLUDED.title, summary = EXCLUDED.summary,
  scenario = EXCLUDED.scenario, instructions = EXCLUDED.instructions, total_marks = EXCLUDED.total_marks,
  grade_bands = EXCLUDED.grade_bands, time_limit_seconds = EXCLUDED.time_limit_seconds,
  pass_score = EXCLUDED.pass_score, max_attempts = EXCLUDED.max_attempts,
  xp_reward = EXCLUDED.xp_reward, token_reward = EXCLUDED.token_reward,
  achievement_code = EXCLUDED.achievement_code, sort_order = EXCLUDED.sort_order;

DELETE FROM lab_capstone_questions WHERE assessment_id = (SELECT id FROM lab_capstone_assessments WHERE code = 'cap-it');
INSERT INTO lab_capstone_questions
  (assessment_id, type, section, competency, cognitive_level, source_refs, prompt, payload, correct,
   explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
SELECT c.id, v.type, v.section, v.competency, v.cognitive_level, v.source_refs::jsonb, v.prompt,
       v.payload::jsonb, v.correct::jsonb, v.explanation, v.rubric::jsonb, v.model_answer,
       v.code_lines::jsonb, v.word_limit::jsonb, v.marks, v.marking, v.sort_order
FROM lab_capstone_assessments c, (VALUES
  ('multiple_choice', 'Section A · Application', 'Secure coding', 'apply', '["IT-01"]'::jsonb, 'The AI assistant produced this search endpoint. What is the BEST fix?', '{"options":["Use a parameterised query: db.query(\"SELECT * FROM listings WHERE title LIKE $1\", [''%'' + q + ''%''])","Strip single quotes from q with a replace() before building the string","Serve the API over HTTPS only","Turn off detailed database error messages"]}'::jsonb, '{"answer_index":0}'::jsonb, 'Parameterised queries keep user input as data, so it can never change the SQL command. The other options do not stop injection.', NULL, NULL, '["app.get(''/search'', async (req, res) => {","  const q = req.query.q;","  const rows = await db.query(","    \"SELECT * FROM listings WHERE title LIKE ''%\" + q + \"%''\"","  );","  res.json(rows);","});"]'::jsonb, NULL, 10, 'auto', 1),
  ('multiple_choice', 'Section A · Application', 'Secure coding', 'apply', '["IT-02"]'::jsonb, 'The sign-up endpoint stores md5(password). What is the BEST improvement?', '{"options":["Keep MD5, because it is one-way and therefore safe","Switch to a salted, slow password-hashing algorithm such as Argon2id or bcrypt","Encrypt passwords with AES and keep the key in the code repository","Store passwords as plain text but restrict who can read the database"]}'::jsonb, '{"answer_index":1}'::jsonb, 'Fast, unsalted hashes can be cracked quickly. Salted, slow algorithms make large-scale cracking expensive. Plain text and a key in the repository expose everyone if either leaks.', NULL, NULL, NULL, NULL, 10, 'auto', 2),
  ('multiple_choice', 'Section A · Application', 'Secure coding', 'analyse', '["IT-03"]'::jsonb, 'An attacker bypasses the app and sends a request straight to the API with a negative listing price. Which control stops this?', '{"options":["Add stricter validation to the Flutter form","Validate and authorise every request on the server","Obfuscate the mobile app''s code","Remove the price field from the form"]}'::jsonb, '{"answer_index":1}'::jsonb, 'Anything the client does can be skipped. The server must enforce its own rules on every request.', NULL, NULL, NULL, NULL, 10, 'auto', 3),
  ('multiple_choice', 'Section B · Scenario', 'Machine learning', 'analyse', '["IT-04","IT-05"]'::jsonb, 'The fake-listing model scores 99% on training data and 71% on validation data. What does this gap MOST likely indicate?', '{"options":["The model is underfitting and needs more capacity","The model is overfitting and may not generalise to real listings","The validation set is too large","This gap is normal and needs no action"]}'::jsonb, '{"answer_index":1}'::jsonb, 'A large training-to-validation gap signals overfitting: the model has learned the training data too closely and generalises poorly.', NULL, NULL, NULL, NULL, 6, 'auto', 4),
  ('multi_select', 'Section B · Scenario', 'Verifying AI output', 'evaluate', '["IT-01","IT-02","IT-03","IT-05"]'::jsonb, 'The AI assistant wrote this review summary. Select ALL statements that are INCORRECT.', '{"options":["Parameterised queries stop SQL injection by keeping user input separate from the SQL command.","Unsalted MD5 is acceptable for storing passwords as long as the database is private.","The validation set is used to tune the model, and the test set is kept for a final, unbiased check.","Because the Flutter app validates inputs, the server can skip validation."]}'::jsonb, '{"indices":[1,3]}'::jsonb, 'Statement 2 is wrong because a leak or insider can still expose fast, unsalted hashes. Statement 4 is wrong because attackers can bypass the app. Statements 1 and 3 are correct.', NULL, NULL, NULL, NULL, 4, 'auto', 5),
  ('extended_response', 'Section B · Scenario', 'Release readiness', 'create', '["IT-01","IT-02","IT-03","IT-04","IT-05"]'::jsonb, 'Write a pre-release report (250 to 400 words). List at least FIVE checks the team must complete before shipping the AI-generated code and the fake-listing model, give a one-line reason for each, and explain how the 99% vs 71% gap should be handled.', '{"word_limit":{"min":250,"max":400}}'::jsonb, NULL, NULL, '[{"criterion":"Lists at least FIVE distinct, valid checks (e.g. human review of AI-generated code, parameterised queries, server-side validation and authorisation, salted slow password hashing, no secrets in code, correct train/validation/test use, monitoring)","marks":12},{"criterion":"Addresses the SQL injection and password-hashing weaknesses identified in the scenario","marks":6},{"criterion":"Addresses the client-side-only validation weakness","marks":5},{"criterion":"Explains the model: the 99% vs 71% gap indicates overfitting, and proposes a fix (more varied data, regularisation or early stopping)","marks":6},{"criterion":"Gives a one-line reason for each check","marks":3},{"criterion":"Organised and clear, covering both the code and the model","marks":3}]'::jsonb, 'Before shipping, the team must complete the following checks. First, a human must review all AI-generated code, because the assistant can produce insecure patterns. Second, replace the string-built SQL with parameterised queries, to stop injection. Third, validate and authorise every request on the server, because clients can bypass the app. Fourth, store passwords with a salted, slow algorithm such as Argon2id or bcrypt, so a leaked database is hard to crack. Fifth, keep secrets out of the code and pin and review dependencies, because they run with our privileges. On the model, the 99% training score against 71% on validation shows overfitting: the model has learned the training listings too closely. We should add more varied training data and apply regularisation or early stopping, then judge the model on a held-out test set that reflects real listings. Finally, add logging and monitoring so we notice problems after release.', NULL, '{"min":250,"max":400}'::jsonb, 35, 'rubric', 6)
) AS v(type, section, competency, cognitive_level, source_refs, prompt, payload, correct, explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
WHERE c.code = 'cap-it';

INSERT INTO achievements (code, name, description) VALUES ('capstone-business', 'Business Consulting Capstone', 'Passed the Business Consulting module capstone assessment.')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

INSERT INTO lab_capstone_assessments
  (code, track_id, title, summary, scenario, instructions, total_marks, grade_bands,
   time_limit_seconds, pass_score, max_attempts, xp_reward, token_reward, achievement_code, sort_order)
VALUES ('cap-bus', (SELECT id FROM industry_tracks WHERE name = 'Business Consulting'),
  'Business Consulting Capstone: Bheki''s Bakehouse', 'Bheki Nkosi owns three bakery branches in Ekurhuleni. You are the consultant he has hired to help him decide where to focus over the next three years.', '{"title":"Bheki''s Bakehouse","background":"Bheki Nkosi owns three bakery branches in Ekurhuleni. You are the consultant he has hired to help him decide where to focus over the next three years.","facts":["Sales have been flat for a year.","Staff turnover is 40% a year across the three branches.","A discount bakery chain recently opened nearby.","The bakery has a strong local reputation and loyal customers.","Orders are still taken on paper, and the system is slow and error-prone.","Demand for corporate catering orders in the area is growing.","Bakery waste should be at most 8% but is currently 12%."]}'::jsonb, '["Answer ALL questions. The paper is worth 75 marks and must be completed in 90 minutes.","Section A (Application, 15 marks): apply the management tools to the scenario.","Section B (Scenario, 20 marks): classify the situation correctly.","Section C (Case study, 40 marks): write a full consulting recommendation.","The case-study scenario is shown at the top of every question for reference.","Write as you would to a client who is not a management specialist."]'::jsonb,
  75, '[{"label":"Distinction","min_percent":75},{"label":"Merit","min_percent":60},{"label":"Competent","min_percent":50},{"label":"Not yet competent","min_percent":0}]'::jsonb, 5400, 60, 3, 70, 15, 'capstone-business', 40)
ON CONFLICT (code) DO UPDATE SET
  track_id = EXCLUDED.track_id, title = EXCLUDED.title, summary = EXCLUDED.summary,
  scenario = EXCLUDED.scenario, instructions = EXCLUDED.instructions, total_marks = EXCLUDED.total_marks,
  grade_bands = EXCLUDED.grade_bands, time_limit_seconds = EXCLUDED.time_limit_seconds,
  pass_score = EXCLUDED.pass_score, max_attempts = EXCLUDED.max_attempts,
  xp_reward = EXCLUDED.xp_reward, token_reward = EXCLUDED.token_reward,
  achievement_code = EXCLUDED.achievement_code, sort_order = EXCLUDED.sort_order;

DELETE FROM lab_capstone_questions WHERE assessment_id = (SELECT id FROM lab_capstone_assessments WHERE code = 'cap-bus');
INSERT INTO lab_capstone_questions
  (assessment_id, type, section, competency, cognitive_level, source_refs, prompt, payload, correct,
   explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
SELECT c.id, v.type, v.section, v.competency, v.cognitive_level, v.source_refs::jsonb, v.prompt,
       v.payload::jsonb, v.correct::jsonb, v.explanation, v.rubric::jsonb, v.model_answer,
       v.code_lines::jsonb, v.word_limit::jsonb, v.marks, v.marking, v.sort_order
FROM lab_capstone_assessments c, (VALUES
  ('multiple_choice', 'Section A · Application', 'Goal setting', 'apply', '["BUS-04"]'::jsonb, 'Which ONE of these is the best SMART goal for the staff turnover problem?', '{"options":["Improve staff morale soon","Reduce staff turnover from 40% to 25% across all three branches by 30 September 2027","Be the best bakery in Ekurhuleni","Cut staff turnover as much as possible this year"]}'::jsonb, '{"answer_index":1}'::jsonb, 'It is specific, measurable (40% to 25%), plausible, relevant to the problem, and has a deadline. The others are vague or have no measure or deadline.', NULL, NULL, NULL, NULL, 8, 'auto', 1),
  ('multiple_choice', 'Section A · Application', 'Controlling', 'apply', '["BUS-05"]'::jsonb, 'The standard for waste is 8% and the measured actual is 12%. What is the most appropriate NEXT step in the control process?', '{"options":["Raise the standard to 12% so the branches meet it","Identify the 4-point gap, find its cause, and take corrective action","Ignore the gap until next quarter''s results","Replace the head baker immediately"]}'::jsonb, '{"answer_index":1}'::jsonb, 'After measuring and comparing against the standard, the manager analyses the deviation and acts on its cause. Changing the standard to fit the results defeats the purpose of control.', NULL, NULL, NULL, NULL, 7, 'auto', 2),
  ('matching', 'Section B · Scenario', 'SWOT analysis', 'apply', '["BUS-02"]'::jsonb, 'Classify each item from the scenario in a SWOT analysis.', '{"left":["Strong local reputation and loyal customers","Slow paper-based ordering system","Growing demand for corporate catering","A discount bakery chain opening nearby"],"right":["Threat (external)","Opportunity (external)","Weakness (internal)","Strength (internal)"]}'::jsonb, '{"mapping":{"Strong local reputation and loyal customers":"Strength (internal)","Slow paper-based ordering system":"Weakness (internal)","Growing demand for corporate catering":"Opportunity (external)","A discount bakery chain opening nearby":"Threat (external)"}}'::jsonb, 'Strengths and weaknesses are internal; opportunities and threats are external.', NULL, NULL, NULL, NULL, 10, 'auto', 3),
  ('matching', 'Section B · Scenario', 'Levels of planning', 'apply', '["BUS-03"]'::jsonb, 'Match each decision to the level of planning it belongs to.', '{"left":["Decide whether to open a fourth branch within three years","Divide the marketing budget between the three branches","Schedule this week''s baking shifts"],"right":["Operational (first-line managers)","Tactical (middle managers)","Strategic (top managers)"]}'::jsonb, '{"mapping":{"Decide whether to open a fourth branch within three years":"Strategic (top managers)","Divide the marketing budget between the three branches":"Tactical (middle managers)","Schedule this week''s baking shifts":"Operational (first-line managers)"}}'::jsonb, 'Strategic decisions are long-term and top-level; tactical decisions are medium-term; operational decisions are day-to-day.', NULL, NULL, NULL, NULL, 10, 'auto', 4),
  ('multi_select', 'Section C · Case study', 'Verifying AI output', 'evaluate', '["BUS-01","BUS-02","BUS-03","BUS-04"]'::jsonb, 'An AI assistant drafted this consulting summary. Select ALL statements that are INCORRECT.', '{"options":["Strengths and weaknesses are factors outside the organisation.","The four classic functions of management are planning, organising, leading and controlling.","\"Improve morale\" is a SMART goal because it is positive and motivating.","Top managers typically set the organisation''s long-term strategic goals."]}'::jsonb, '{"indices":[0,2]}'::jsonb, 'Statement 1 is wrong: strengths and weaknesses are internal. Statement 3 is wrong: a goal needs to be specific, measurable and time-bound. Statements 2 and 4 are correct.', NULL, NULL, NULL, NULL, 4, 'auto', 5),
  ('extended_response', 'Section C · Case study', 'Consulting recommendation', 'create', '["BUS-02","BUS-04","BUS-05"]'::jsonb, 'Write a recommendation (250 to 400 words) to Bheki. Name ONE strategic priority justified by your SWOT analysis, state a SMART goal for it, describe how he will control progress towards the goal, and propose one action to address a weakness or the waste problem.', '{"word_limit":{"min":250,"max":400}}'::jsonb, NULL, NULL, '[{"criterion":"Names one strategic priority and links it clearly to specific items in the SWOT analysis","marks":7},{"criterion":"States a SMART goal: specific and measurable","marks":6},{"criterion":"The goal is achievable and relevant to the priority, and has a deadline","marks":6},{"criterion":"Describes the control process: a standard, measuring actual results, comparing, and corrective action","marks":9},{"criterion":"Proposes one action to address a weakness (paper ordering) or the waste problem","marks":5},{"criterion":"Clear, professional wording a non-specialist can follow","marks":3}]'::jsonb, 'Bheki, I recommend that your priority is to build a corporate catering business. Your strong local reputation and loyal customers are strengths, and demand for corporate catering is growing, which is an opportunity. This also helps against the threat from the discount chain, because you would compete on service and quality rather than on price. Your slow, paper-based ordering system is a weakness, so we should replace it with a simple digital system before we chase large orders, and we should also look at why waste is 12% against a standard of 8%. My goal is that corporate catering will bring in 15% of total sales by 30 June 2028. To control progress, set a quarterly target as the standard, measure the actual catering sales each month, compare them with the target, and if you fall short, investigate the cause, such as slow quotations or too few staff, and act on it. Review the numbers with your branch managers every month, and address staff turnover because it affects service quality. This gives you a clear, measurable plan that builds on what you already do well.', NULL, '{"min":250,"max":400}'::jsonb, 36, 'rubric', 6)
) AS v(type, section, competency, cognitive_level, source_refs, prompt, payload, correct, explanation, rubric, model_answer, code_lines, word_limit, marks, marking, sort_order)
WHERE c.code = 'cap-bus';
